layers.vertex:
attribute vec3 aO; attribute vec2 aP; attribute float aT, aV; uniform float uTime; varying float vY, vU, vK, vA; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    vec3 path(float a, float R, float k){                             // centre of thread k at ring angle a: twisted around the ring core in 3D
      float tw = 7.*a + k*2.0944 - uTime*1.1, A = .02;          // threads kept close together
      vec3 rad = vec3(cos(a), 0., sin(a));
      float y = 0.95 + .045*sin(2.*a + uTime*.7) + .025*sin(3.*a - uTime*1.1);   // the whole ring undulates gently in height
      return vec3(cos(a)*R, y, sin(a)*R) + A*(cos(tw)*rad + sin(tw)*vec3(0., 1., 0.));
    }
    void main(){ if (aV < .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float u = uTime - aT, R = mix(.08, 0.58, eox(clamp(u/.3, 0., 1.)));
      float a = (position.x + .5)*6.28318 + aP.x, k = aP.y;
      vec3 P = aO + path(a, R, k), T = normalize(path(a + .004, R, k) - path(a, R, k));
      vec3 side = normalize(cross(T, P - cameraPosition));             // ribbon always faces the camera: a thread of light
      vY = position.y*2.; vU = u; vK = k; vA = a;
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*.075, 1.); /* wider ribbon: room for a soft plasma body */ }

layers.fragment:
uniform float uTime; uniform vec3 uFire, uIce, uBolt; varying float vY, vU, vK, vA;
    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    void main(){
      vec3 c = vK < .5 ? uFire : (vK < 1.5 ? uIce : uBolt);
      float pk = vU < .033 ? 1.6 : 1. + .5*exp(-max(vU - .033, 0.)*10.);
      // plasma / cloud: a soft body whose density drifts along the thread with two octaves of noise; the edge wobbles too
      vec2 q = vec2(vA*9. - uTime*.9 + vK*7.3, vY*1.6);
      float n = vn(q)*.6 + vn(q*2.3 + vec2(uTime*.4, 3.1))*.4;
      float wob = vY + (vn(vec2(vA*14. + uTime*.7, vK*5.)) - .5)*.5;
      float body = exp(-wob*wob*4.)*(.35 + .65*n);
      float core = exp(-wob*wob*22.)*(.4 + .6*n);
      vec3 o = (c*(body*.32 + core*.28) + mix(c, vec3(1.), .35)*core*.1)*pk;
      o *= smoothstep(1., .75, abs(vY));                                   // zero at the ribbon edge
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.);
    }
